/**
 * Phase 28 — Public, unauthenticated certificate verification. Anyone
with the `certId` (the `user_progress.id` UUID of a completed
project) can confirm authenticity and view an evidence summary
derived from the Phase 26/27 trustworthy completion model
(step-level passed counts, evidence-hash counts, and project-scoped
XP ledger rollup).

Privacy contract: never returns `email`, `clerkId`, internal user
IDs, Stripe identifiers, raw `submissionExcerpt`, raw submission
content, raw per-step `submissionSha256` values, or data from any
project other than the one the certificate is for. The
`evidenceHashCount` is a non-leaky integer (count only).

Returns 404 — never 403 — for malformed, missing, or non-completed
certificates (no existence leak).

 * @summary Public certificate verification (Phase 28)
 */
export const VerifyCertificateParams = zod.object({
  certId: zod.coerce
    .string()
    .describe("UUID of the `user_progress` row for a completed project"),
});

export const VerifyCertificateResponse = zod
  .object({
    certId: zod
      .string()
      .describe("UUID of the user_progress row for this completion"),
    recipientName: zod.string(),
    recipientUsername: zod.string().nullable(),
    projectTitle: zod.string(),
    projectSlug: zod.string(),
    completedAt: zod.coerce.date(),
    firstStepCompletedAt: zod.coerce
      .date()
      .nullable()
      .describe(
        "Earliest passed step completion timestamp for this learner on\nthis project. Null when no step-completion rows exist (legacy\npre-Phase-26 completions).\n",
      ),
    durationSeconds: zod
      .number()
      .nullable()
      .describe(
        "completedAt − firstStepCompletedAt, in whole seconds. Null\nwhen firstStepCompletedAt is null. Clamped to ≥ 0.\n",
      ),
    stepsCompleted: zod
      .number()
      .describe(
        "Count of distinct passed steps for this learner on this\nproject. Always ≤ totalSteps.\n",
      ),
    totalSteps: zod
      .number()
      .describe("Required step count from the project definition."),
    evidenceHashCount: zod
      .number()
      .describe(
        "Count of passed step rows whose submission_sha256 is\nnon-null. Phase 26 evidence; legacy pre-P26 rows are null and\ndo not count. Always ≤ stepsCompleted. Raw hash values are\nnever exposed.\n",
      ),
    totalXpEarned: zod
      .number()
      .describe(
        "Sum of xp_transactions.amount for this learner scoped to this\nproject (metadata.projectId match). Reflects the Phase 26 XP\nledger; legacy pre-P26 awards (which were not ledger-written)\ncontribute 0 here.\n",
      ),
    issuer: zod.string(),
  })
  .describe(
    "Phase 28 — Public certificate verification payload. Strictly\nnon-private; never contains email, clerkId, internal user IDs,\nStripe identifiers, raw submissions, raw evidence hashes, or\ncross-project data.\n",
  );

/**
 * Phase 29 — Authenticated learner-facing portfolio. Returns one
`PortfolioEvidence` row per completed project owned by the
requesting user, enriched with the Phase 26/27 trustworthy
completion evidence (passed-step count, evidence-hash count,
project-scoped XP ledger rollup, first-step → completed span)
using the same SQL fragments and clamps as the public Phase 28
`/verify/:certId` route.

Privacy contract: `userId` is sourced EXCLUSIVELY from the
authenticated session. No path/query/body parameter accepts a
userId, username, or project-ownership claim. Response never
contains `email`, `clerkId`, internal user IDs, Stripe
identifiers, raw submissions, raw evidence hashes, or any
data scoped to a different user or project. Hidden
(`learner_visible=false`) and soft-deleted projects are
silently dropped — same anti-leak posture as `/dashboard`.

 * @summary Authenticated learner portfolio (Phase 29)
 */
export const GetUserPortfolioResponse = zod
  .object({
    completedCount: zod
      .number()
      .describe("Length of items[] (post hidden\/deleted drop)"),
    totalProjectXp: zod.number().describe("Sum over items[].totalXpEarned"),
    evidenceBackedCount: zod
      .number()
      .describe("Count of items where evidenceHashCount ≥ 1"),
    items: zod.array(
      zod
        .object({
          certId: zod
            .string()
            .describe(
              "UUID of the user_progress row — shareable via \/verify\/{certId}",
            ),
          projectSlug: zod.string(),
          projectTitle: zod.string(),
          course: zod
            .string()
            .describe("Course slug from projects.course (no heuristics)"),
          difficulty: zod.enum(["beginner", "intermediate", "advanced"]),
          completedAt: zod.coerce.date(),
          firstStepCompletedAt: zod.coerce.date().nullable(),
          durationSeconds: zod
            .number()
            .nullable()
            .describe("completedAt − firstStepCompletedAt, clamped ≥ 0"),
          stepsCompleted: zod.number().describe("Always ≤ totalSteps"),
          totalSteps: zod.number(),
          evidenceHashCount: zod
            .number()
            .describe(
              "Count of passed rows with non-null submission_sha256. Raw hashes never exposed. Always ≤ stepsCompleted.",
            ),
          totalXpEarned: zod
            .number()
            .describe(
              "Sum of project-scoped xp_transactions for this learner. Legacy pre-P26 rows contribute 0.",
            ),
          verifyUrl: zod.string().describe("Relative URL — \/verify\/{certId}"),
          printUrl: zod
            .string()
            .describe("Relative URL — \/certificates\/{projectSlug}\/print"),
          topRole: zod
            .string()
            .nullable()
            .describe("First entry of project.jobOutcomes.roles, if any"),
        })
        .describe(
          "Phase 29 — Single completed project for the authenticated learner.\nReuses Phase 28 evidence semantics (same SQL aggregates, same\nclamps) but adds learner-facing fields (`course`, `difficulty`,\n`topRole`, `verifyUrl`, `printUrl`). Excludes the\npublic-cert-only fields (`recipientName`, `recipientUsername`,\n`issuer`) since the surface is the learner's own.\n",
        ),
    ),
  })
  .describe(
    "Phase 29 — Authenticated portfolio payload. `userId` is intentionally\nabsent — clients already know who they are. Summary aggregates are\ncomputed over `items[]` so any future hidden\/deleted-project drop\nis reflected consistently.\n",
  );

/**
 * Phase 60A/60B/60C — Authenticated, read-only. Returns a deterministic,
recruiter-readable artifact bundle (README.md, VALIDATION_EVIDENCE.md,
LIMITATIONS.md, LEARNER_REFLECTION_TEMPLATE.md, and optionally
DATASET_NOTES.md) generated from THIS user's safe completion and
evidence records for the given project.

Privacy contract: `userId` is sourced EXCLUSIVELY from the
authenticated session — no path/query/body parameter accepts a userId
or ownership claim. The response NEVER contains validationConfig,
expectedRows, expectedRowsHash, reference solution queries, comparator
internals, raw submissions, secrets, or over-claiming
authorship/job-guarantee/certification copy (guaranteed by the
assembly chokepoint, the leak-free-by-construction generator input
model, and a runtime honest-claim guard).

Returns 404 — never 403 — when the project is hidden, soft-deleted,
unknown, or the user is not enrolled (no hidden-project existence leak).

 * @summary Authenticated portfolio artifact bundle (Phase 60C)
 */
export const GetPortfolioArtifactParams = zod.object({
  projectSlug: zod.coerce
    .string()
    .describe("Slug of a project the authenticated user is enrolled in"),
});

export const GetPortfolioArtifactResponse = zod
  .object({
    projectSlug: zod.string(),
    generatedAt: zod.coerce.date(),
    files: zod
      .object({
        "README.md": zod.string(),
        "VALIDATION_EVIDENCE.md": zod.string(),
        "LIMITATIONS.md": zod.string(),
        "LEARNER_REFLECTION_TEMPLATE.md": zod.string(),
        "DATASET_NOTES.md": zod.string().optional(),
      })
      .describe("Map of artifact filename → markdown contents."),
  })
  .describe(
    "Phase 60C — deterministic, leak-safe portfolio artifact bundle for a\nsingle completed\/enrolled project of the authenticated user. `files`\nmaps each artifact filename to its markdown contents. Contains only the\nPhase-60A generator output — never validationConfig, expectedRows,\nanswer keys, reference queries, raw submissions, or secrets.\n",
  );

/**
 * Phase 60G — Authenticated, read-only. Returns a deterministic,
GitHub-ready local repository bundle for THIS user's project: the
Phase-60A Markdown evidence files plus a machine-readable
`atlas-portfolio.json` and an optional learner-evidence
`evidence/submission-summary.md`. The learner downloads the JSON and
MANUALLY reconstructs/uploads the repository to GitHub.

No OAuth, no token, no direct push, no publishing. The privacy +
no-leak contract is identical to the portfolio-artifact route: `userId`
comes EXCLUSIVELY from the authenticated session; the response NEVER
contains validationConfig, expectedRows, expectedRowsHash, reference
queries, comparator internals, raw submissions, secrets, or
over-claiming copy (assembly chokepoint + leak-free generator input +
export path guard + runtime honest-claim guard). Returns 404 — never
403 — for a hidden/deleted/unknown project or a non-enrolled user.

 * @summary Authenticated GitHub-ready portfolio repository export (Phase 60G)
 */
export const GetPortfolioRepositoryParams = zod.object({
  projectSlug: zod.coerce
    .string()
    .describe("Slug of a project the authenticated user is enrolled in"),
});

export const GetPortfolioRepositoryResponse = zod
  .object({
    projectSlug: zod.string(),
    generatedAt: zod.coerce.date(),
    format: zod.enum(["github-ready-repository"]),
    files: zod
      .record(zod.string(), zod.string())
      .describe("Map of repo-relative file path → file contents."),
  })
  .describe(
    "Phase 60G — deterministic, leak-safe GitHub-ready repository bundle for a\nsingle completed\/enrolled project of the authenticated user. `files`\nmaps each repo-relative path (e.g. `README.md`, `atlas-portfolio.json`,\n`evidence\/submission-summary.md`) to its contents. Contains only the\nPhase-60A generator output + safe derived metadata — never\nvalidationConfig, expectedRows, answer keys, reference queries, raw\nsubmissions, or secrets. The learner reconstructs a folder named\n`projectSlug` from `files` and uploads it to GitHub manually.\n",
  );

